<?php
namespace App\Http\Controllers;use App\Exports\{TransportControlExport,TransportOperationExport};use App\Models\{TransportDocument,TransportService,TransportServiceIssue};use App\Services\{TransportAnalyticsService,TransportAuditService};use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Http\Request;use Maatwebsite\Excel\Facades\Excel;
class TransportControlReportController extends Controller {private function filters(Request$r):array{$r->validate(['from'=>'required|date','to'=>'required|date|after_or_equal:from']);return array_merge(['from'=>$r->from,'to'=>$r->to,'period'=>'custom'],$r->only(['transport_route_id','planned_vehicle_id','planned_driver_id','status']));}public function management(Request$r,string$type,TransportAnalyticsService$a,TransportAuditService$audit){abort_unless(in_array($type,['daily','weekly','monthly','executive']),404);$f=$this->filters($r);$c=$r->user()->company_id;$summary=$a->summary($c,$f);$services=$a->query($c,$f)->with(['vehicle','actualVehicle','driver.employee','actualDriver.employee','issues'])->orderBy('service_date')->get();$documents=TransportDocument::forCompany($c)->with('type')->where('is_current',1)->where(function($q)use($f){$q->whereNull('expires_at')->orWhereDate('expires_at','<=',$f['to']);})->get();$audit->record($c,'transport_report_generated','report',0,$r->user()->id,['type'=>$type,'from'=>$f['from'],'to'=>$f['to']]);return Pdf::loadView('pdf.transport_management',compact('type','f','summary','services','documents'))->setPaper('a4','landscape')->download("informe-transporte-{$type}.pdf");}public function issues(Request$r,TransportAuditService$audit){$f=$this->filters($r);$q=TransportServiceIssue::forCompany($r->user()->company_id)->with(['service.actualVehicle','service.actualDriver.employee'])->whereBetween('occurred_at',[$f['from'].' 00:00:00',$f['to'].' 23:59:59']);foreach(['issue_type','severity','status']as$x)if($r->filled($x))$q->where($x,$r->$x);$issues=$q->get();$audit->record($r->user()->company_id,'transport_report_generated','report',0,$r->user()->id,['type'=>'issues']);return Pdf::loadView('pdf.transport_issues',compact('issues','f'))->setPaper('a4','landscape')->download('novedades-transporte.pdf');}public function documents(Request$r){$docs=TransportDocument::forCompany($r->user()->company_id)->with('type')->where('is_current',1)->get();return Pdf::loadView('pdf.transport_documents',compact('docs'))->setPaper('a4','landscape')->download('control-documental-transporte.pdf');}public function indicatorsExcel(Request$r,TransportAnalyticsService$a){$f=$this->filters($r);return Excel::download(new TransportControlExport($r->user()->company_id,$f,$a),'indicadores-transporte.xlsx');}public function historyExcel(Request$r){$f=$this->filters($r);return Excel::download(new TransportOperationExport($r->user()->company_id,$f),'historico-transporte.xlsx');}}
